class RowTest {static void Check(bool ok){if(!ok)throw new Exception("Row test failed");}static XUiV_Label L(XUiC_StatistikRow r,string id){return (XUiV_Label)r.GetChildById(id).ViewComponent;}static int Main(){try {var d=BloodmoonLog.Parse("=== Blutmond Tag 14 END test ===\nA start=0 end=10 bm_kills=10\nB start=0 end=10 bm_kills=10\n=== Blutmond Tag 7 END test ===\nA start=0 end=20 bm_kills=20\nB start=0 end=2 bm_kills=2\nC start=0 end=0 bm_kills=0\n");var r=new XUiC_StatistikRow();r.Render(d,"A",0,20,0);Check(L(r,"record").Text=="20"&&L(r,"record").Color.Value==1&&L(r,"value0").Color.Value==1);r.Render(d,"B",0,20,1);Check(L(r,"record").Text=="10"&&L(r,"record").Color.Value==0&&L(r,"value0").Color.Value==1&&L(r,"value1").Color.Value==0);r.Render(d,"C",0,20,2);Check(L(r,"value0").Text=="—"&&L(r,"value1").Text=="0");r.Render(d,"A",1,20,0);Check(L(r,"record").Text=="20");r.Render(d,null,0,20,3);Check(L(r,"record").Text==""&&L(r,"value0").Color.Value==0);Console.WriteLine("Rekorde, Nachtmaxima, Gleichstand, fehlende Werte, Nullwerte und Seitenwechsel bestanden.");return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}}
